### 🚛 Vérification de Capacité

**Ordre sélectionné :** {{ Table_Ordres.selectedRow ? Table_Ordres.selectedRow.ordre_id : "Aucun" }}
**Poids total des matériels :** {{ 
  (Select_Materiel.selectedOptionValues || []).reduce((sum, selectedVal) => {
    let item = (get_materiels_disponibles.data || []).find(m => String(m.id) === String(selectedVal));
    let valPoids = item ? (item.poids_kg ?? item.poids ?? item.weight ?? 0) : 0;
    return sum + Number(valPoids);
  }, 0)
}} kg
**Charge max du camion :** {{ Select_Camion.selectedOptionValue ? ((get_camions.data || []).find(c => String(c.id) === String(Select_Camion.selectedOptionValue))?.charge_utile_kg || (get_camions.data || []).find(c => String(c.id) === String(Select_Camion.selectedOptionValue))?.charge_max_kg || 0) : 0 }} kg

**Statut charge :** {{ 
  !Select_Camion.selectedOptionValue 
    ? "Veuillez sélectionner un camion" 
    : (!Select_Materiel.selectedOptionValues || Select_Materiel.selectedOptionValues.length === 0)
      ? "Veuillez sélectionner au moins un matériel"
      : (((Select_Materiel.selectedOptionValues || []).reduce((sum, selectedVal) => {
            let item = (get_materiels_disponibles.data || []).find(m => String(m.id) === String(selectedVal));
            let valPoids = item ? (item.poids_kg ?? item.poids ?? item.weight ?? 0) : 0;
            return sum + Number(valPoids);
          }, 0)) <= ((get_camions.data || []).find(c => String(c.id) === String(Select_Camion.selectedOptionValue))?.charge_utile_kg || (get_camions.data || []).find(c => String(c.id) === String(Select_Camion.selectedOptionValue))?.charge_max_kg || 0))
        ? "✅ Poids conforme" 
        : "⚠️ SURCHARGE DÉTECTÉE !" 
}}
